#!/usr/bin/env python3
"""Wolfram|Alpha query script for scientific calculations."""
import sys
import os
import json
import urllib.request
import urllib.parse

def query_wolfram(query):
    """Query Wolfram|Alpha API and return result."""
    app_id = os.environ.get('WOLFRAM_APP_ID', '')
    if not app_id:
        # If no API key, return a placeholder indicating manual verification
        return f"[WOLFRAM_API_NOT_CONFIGURED] Query: {query}"

    url = f"https://api.wolframalpha.com/v1/result?appid={app_id}&i={urllib.parse.quote(query)}"
    try:
        with urllib.request.urlopen(url, timeout=10) as response:
            return response.read().decode('utf-8')
    except Exception as e:
        return f"[ERROR] {str(e)}"

if __name__ == '__main__':
    if len(sys.argv) < 2:
        print("Usage: python3 wolfram_query.py <query>")
        sys.exit(1)

    query = ' '.join(sys.argv[1:])
    result = query_wolfram(query)
    print(result)
